def summarize_usage(events):
    input_max = 0
    output_max = 0

    for event in events:
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)

        if input_count < 0 or output_count < 0:
            raise ValueError("Negative token count not allowed")

        if input_count > input_max:
            input_max = input_count
        if output_count > output_max:
            output_max = output_count

    return {'input': input_max, 'output': output_max}

