def merge_tool_results(calls, results):
    # Check for duplicate call ids
    seen_ids = set()
    for call in calls:
        id_val = call['id']
        if id_val in seen_ids:
            raise ValueError("Duplicate call id")
        seen_ids.add(id_val)

    # Build a mapping from id to the last result's content
    # Ignore results with unknown ids (ids not in calls)
    result_map = {}
    for result in results:
        id_val = result['id']
        # Only store if the id is in calls (known id)
        if id_val in seen_ids:
            content = result.get('content', '')
            result_map[id_val] = content

    # Build the result list in call order
    output = []
    for call in calls:
        id_val = call['id']
        if id_val in result_map:
            output.append({'id': id_val, 'status': 'done', 'content': result_map[id_val]})
        else:
            output.append({'id': id_val, 'status': 'pending'})

    return output

